parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "estado": {
      "type": "string",
      "enum": [ "APROBADO","ESCALADO", "FALTA_DATO", "FUERA_DE_POLITICA"],
      "description": "Decisión del validador."
    },
    "tipo_hora_extra": {
      "type": ["string", "null"],
      "description": "Categoría identificada según la tool (ej: hora_extra_dia_habil, hora_extra_nocturna, hora_extra_sabado, hora_extra_domingo, hora_extra_feriado, guardia_pasiva, traslado_fuera_horario, capacitacion_fuera_horario). Null si no se determinó o si estado es FUERA_DE_POLITICA."
    },
    "horas_declaradas": {
      "type": "number",
      "description": "Horas extra declaradas en la solicitud."
    },
    "limite_categoria": {
      "type": ["number", "null"],
      "description": "Límite máximo de horas para la categoría identificada, según la tool. Null si no aplica."
    },
    "requiere_autorizacion_previa": {
      "type": ["boolean", "null"],
      "description": "Si la categoría exige autorización previa según la tool. Null si no se determinó."
    },
    "requiere_codigo_proyecto": {
      "type": ["boolean", "null"],
      "description": "Si la categoría identificada exige código de proyecto, según la tool. Null si no se determinó."
    },
    "motivo_escalado": {
      "type": ["string", "null"],
      "enum": ["SUPERA_LIMITE", "REQUIERE_AUTORIZACION_PREVIA", "TIPO_AMBIGUO", "FALLO_TOOL", null],
      "description": "Causa concreta de la escalada. Null si estado no es ESCALADO."
    },
    "supuesto_aplicado": {
      "type": ["string", "null"],
      "description": "Si se asumió una categoría por defecto sin preguntar (Regla 5), explica cuál y por qué. Null si no aplicó ningún supuesto."
    },
    "dato_faltante": {
      "type": ["string", "null"],
      "description": "Pregunta cerrada de opción múltiple sobre el único dato puntual que falta. Null salvo cuando estado = FALTA_DATO."
    },
    "detalle": {
      "type": "string",
      "description": "Justificación citando fecha, horas y proyecto/motivo concretos de la solicitud."
    }
  },
  "required": ["estado", "horas_declaradas", "detalle"],
  "additionalProperties": false
}

